import './index.less'

// 文案促销机动板块
class ProductTextPromotion {
  constructor() {
    // 获取 文案促销 DOM
    this.DOM = document.querySelector('#app-text-promotion')

    const {
      textPromotionText, textPromotionTextMainColor, showCountdown, endsInText,
      countdownStartStr, countdownEndStr, countdownLabelStr = '', countdownTextColor,
      countdownBgColor, countdownNumberColor,
    } = this.DOM.dataset

    this.i18nText = {
      textPromotionTextMainColor,
      endsInText,
      countdownLabel: countdownLabelStr?.split(','),
      countdownTextColor,
      countdownBgColor,
      countdownNumberColor,
    }

    if (textPromotionText || (showCountdown == 'true' && countdownStartStr && countdownEndStr)) {
      this.DOM.innerHTML = this.renderDOM({ textPromotionText, textPromotionTextMainColor, showCountdown, })

      this.init({ showCountdown, countdownStartStr, countdownEndStr, })
    }
  }
  init({ showCountdown, countdownStartStr, countdownEndStr, }) {
    // 倒计时 DOM
    this.daysDOM = this.DOM.querySelector('[data-countdown-days]')
    this.hrsDOM = this.DOM.querySelector('[data-countdown-hrs]')
    this.minsDOM = this.DOM.querySelector('[data-countdown-mins]')
    this.secsDOM = this.DOM.querySelector('[data-countdown-secs]')

    if (showCountdown == 'true') {
      // 渲染数据
      this.initData({
        startTime: new Date(countdownStartStr).getTime(),
        endTime: new Date(countdownEndStr).getTime(),
      })
    } else {
      this.DOM.parentElement.style.display = 'block'
    }
  }
  async initData({ startTime, endTime, }) {
    const { api, cr, shopId, } = window.pageInfo
    // 获取服务器时间
    const url = `${api}/osconsumerapi/v1/com/get-server-time?shopify_shop_id=${shopId || ''}&cr=${cr || ''}`
    const response = await fetch(url, {
      method: "GET",
      mode: "cors",
      cache: "no-cache",
      headers: {
        "Content-Type": "application/json",
      },
    });
    const { data, } = await response.json()
    const serverTime = new Date(data.datetime).getTime()

    if (serverTime >= startTime) {
      this.DOM.parentElement.style.display = 'block'
      this.tick(endTime, serverTime)
    } else {
      this.DOM.parentElement.removeChild(this.DOM)
    }
  }
  tick(target, current) {
    const leftTime = (target - current) / 1000
    let days, hours, minutes, seconds

    if (leftTime <= 0) {
      this.timer && clearTimeout(this.timer)

      // 移除本身 DOM
      this.DOM.parentElement.removeChild(this.DOM)
    } else {
      days = String( parseInt(leftTime/60/60/24) ).padStart(2, '0')
      hours = String( parseInt(leftTime/60/60%24) ).padStart(2, '0')
      minutes = String( parseInt(leftTime/60%60) ).padStart(2, '0')
      seconds = String( parseInt(leftTime%60) ).padStart(2, '0')

      this.daysDOM.innerText = days
      this.hrsDOM.innerText = hours
      this.minsDOM.innerText = minutes
      this.secsDOM.innerText = seconds

      this.timer = setTimeout(() => this.tick(target, current + 1000), 1000)
    }
  }
  // 渲染 富文本
  renderDOM({textPromotionText, textPromotionTextMainColor, showCountdown}) {
    // 高亮 em 标签
    const richText = this.addStyleToEmTags(textPromotionText, `color:${textPromotionTextMainColor}`)

    const daysItem = this.renderTimeItem('days', this.i18nText.countdownLabel[0] || '')
    const HrsItem = this.renderTimeItem('hrs', this.i18nText.countdownLabel[1] || '')
    const MinsItem = this.renderTimeItem('mins', this.i18nText.countdownLabel[2] || '')
    const secsItem = this.renderTimeItem('secs', this.i18nText.countdownLabel[3] || '')

    return `
      ${
        richText ? `
          <div class="text-promotion-richtext font-medium text-#666 text-28 leading-42 lg:j-text-16 lg:j-leading-24 xl:a-text-16 xl:a-leading-24">
            ${richText}
          </div>
        ` : ''
      }
      ${
        showCountdown == 'true' ? `
          <div class="flex items-start mt-24 lg:j-mt-8 xl:a-mt-8">
            <div
              class="font-normal text-26 mr-16 leading-56 lg:j-text-14 lg:j-mr-12 lg:j-leading-28 xl:a-text-14 xl:a-mr-12 xl:a-leading-28"
              style="color:${this.i18nText.countdownTextColor}"
            >${this.i18nText.endsInText}</div>
            <div class="flex flex-col">
              <div class="flex items-start justify-center">
                ${daysItem}
                <span
                  class="flex-center font-semibold w-50 h-50 text-36 lg:j-w-25 lg:j-h-26 lg:j-text-18 xl:a-w-25 xl:a-h-26 xl:a-text-18"
                  style="color:${this.i18nText.countdownBgColor}"
                >:</span>
                ${HrsItem}
                <span
                  class="flex-center font-semibold w-50 h-50 text-36 lg:j-w-25 lg:j-h-26 lg:j-text-18 xl:a-w-25 xl:a-h-26 xl:a-text-18"
                  style="color:${this.i18nText.countdownBgColor}"
                >:</span>
                ${MinsItem}
                <span
                  class="flex-center font-semibold w-50 h-50 text-36 lg:j-w-25 lg:j-h-26 lg:j-text-18 xl:a-w-25 xl:a-h-26 xl:a-text-18"
                  style="color:${this.i18nText.countdownBgColor}"
                >:</span>
                ${secsItem}
              </div>
            </div>
          </div>
        ` : ''
      }
    `
  }
  // 高亮 em 标签
  addStyleToEmTags(str, customStyle) {
    return str.replace(/<em\b(?![^>]*\bstyle=)[^>]*>/gi, `<em style="${customStyle}">`);
  }
  // 渲染单个的 item
  renderTimeItem(name, label) {
    return `
      <div class="flex-center flex-col gap-y-4 lg:j-gap-y-2 xl:a-gap-y-2">
        <span
          class="flex-center font-medium leading-normal min-w-60 h-56 rounded-8 text-30 px-10 lg:j-min-w-30 lg:j-h-28 lg:j-rounded-5 lg:j-text-16 lg:j-px-5 xl:a-min-w-30 xl:a-h-28 xl:a-rounded-5 xl:a-text-16 xl:a-px-5"
          style="color:${this.i18nText.countdownNumberColor};background-color:${this.i18nText.countdownBgColor}"
          data-countdown-${name}
        ></span>
        ${
          label ? `
            <span
              class="font-normal text-22 lg:j-text-10 xl:a-text-10"
              style="color:${this.i18nText.countdownTextColor}"
            >${label}</span>
          ` : ''
        }
      </div>
    `
  }
}

document.addEventListener('DOMContentLoaded', () => {
  new ProductTextPromotion()
})
